"""Render the effective config to /etc/wifibroadcast.cfg (a generated artifact)."""

import os

HEADER = (
    "# generated by fpvd — do not edit.\n"
    "# source of truth: /etc/fpvd/{defaults,config}.json\n"
)


def _lit(value) -> str:
    """Render a value as a Python literal — wfb-ng's config parser runs
    ast.literal_eval on every value, so strings MUST be quoted (e.g. a peer
    URL renders as 'connect://127.0.0.1:14550', not connect://...)."""
    return repr(value)


def render_cfg(effective: dict) -> str:
    link = effective.get("link", {})
    wfb = effective.get("wfb", {})
    lines = [HEADER, "[common]"]
    lines.append(f"wifi_channel = {_lit(link['channel'])}")
    lines.append(f"wifi_region = {_lit(link['region'])}")
    if link.get("txpower") is not None:
        # NOTE: wfb-ng wifi_txpower is in mBm; leave unset to keep the driver default.
        lines.append(f"wifi_txpower = {_lit(link['txpower'])}")
    # link.linkId is NOT emitted: wfb-ng derives link_id by hashing link_domain,
    # there is no link_id config key. The default link_domain already yields the
    # shared id. (Wiring linkId -> link_domain is future work.)

    # The card width = max(all service bandwidths). gs_video carries the full
    # link width; the uplink services (mavlink/tunnel) cap at 20 MHz, but narrow
    # to the link width when it is below 20 so the card can actually reach 10 MHz.
    # (-B 10 and -B 20 are wire-identical — both radiotap BW_20 — so a 10 MHz
    # link just needs the card at 10 MHz via iw; see wfb-ng src/tx.cpp.)
    width = link["width"]
    uplink_bw = min(width, 20)

    lines.append("")
    lines.append("[gs_video]")
    lines.append(f"bandwidth = {_lit(width)}")

    lines.append("")
    lines.append("[gs_mavlink]")
    mav = wfb.get("mavlink", {})
    if mav.get("peer"):
        lines.append(f"peer = {_lit(mav['peer'])}")
    lines.append(f"bandwidth = {_lit(uplink_bw)}")

    lines.append("")
    lines.append("[gs_tunnel]")
    lines.append(f"bandwidth = {_lit(uplink_bw)}")

    # raw passthrough: {section: {key: value}} — values rendered as literals too
    for section, kv in (wfb.get("raw") or {}).items():
        lines.append("")
        lines.append(f"[{section}]")
        for key, value in kv.items():
            lines.append(f"{key} = {_lit(value)}")

    return "\n".join(lines) + "\n"


def write_cfg(path: str, text: str) -> None:
    """Atomic write; previous content preserved as <path>.bak."""
    if os.path.exists(path):
        os.replace(path, path + ".bak")
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        f.write(text)
    os.replace(tmp, path)


def restore_bak(path: str) -> None:
    """Restore the previous cfg saved by write_cfg (<path>.bak -> <path>)."""
    bak = path + ".bak"
    if os.path.exists(bak):
        os.replace(bak, path)
